### C++

```cpp
#include <bits/stdc++.h>
using namespace std;
using LL = long long;
const LL INF = 1e18;

struct Edge {
    int to, w, t;
};

struct State {
    LL d;
    int u, t;
    // 小根堆需要重载大于号
    bool operator>(const State& other) const {
        return d > other.d;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    // c[1..n] 切换延迟
    vector<int> c(n + 1);
    for (int i = 1; i <= n; ++i) {
        cin >> c[i];
    }

    vector<vector<Edge>> g(n + 1);
    for (int i = 0; i < m; ++i) {
        int u, v, w, t;
        cin >> u >> v >> w >> t;
        t--;   // 内部用 0/1
        g[u].push_back({v, w, t});
        g[v].push_back({u, w, t});
    }

    // dist[i][0] 类型1, dist[i][1] 类型2
    vector<vector<LL>> dist(n + 1, vector<LL>(2, INF));
    vector<vector<bool>> vis(n + 1, vector<bool>(2, false));
    dist[1][0] = dist[1][1] = 0;

    priority_queue<State, vector<State>, greater<State>> pq;
    pq.push({0, 1, 0});
    pq.push({0, 1, 1});

    while (!pq.empty()) {
        State cur = pq.top();
        pq.pop();
        int u = cur.u, t = cur.t;
        if (vis[u][t]) continue;
        vis[u][t] = true;

        for (auto &e : g[u]) {
            int v = e.to, nxtT = e.t;
            LL trans = (nxtT == t) ? 0 : c[u];   // 通道类型不同，加 c[u]
            LL newDist = dist[u][t] + trans + e.w;
            if (newDist < dist[v][nxtT]) {
                dist[v][nxtT] = newDist;
                pq.push({newDist, v, nxtT});
            }
        }
    }

    cout << min(dist[n][0], dist[n][1]) << '\n';
    return 0;
}
